import { NATIVE_CAPABILITIES } from "../../core/engine.js";
import type { EngineContext, PlayerEngine } from "../../core/engine.js";
import { createPlayerError } from "../../core/errors.js";
import {
  bindMediaElement,
  bufferedEnd,
  safeDuration,
  waitForMetadata,
} from "../../core/media-events.js";
import type { AudioTrackInfo, QualityLevel, TextTrackInfo } from "../../core/types.js";
import { clamp } from "../../core/utils.js";
import { createMediaElement, removeElement } from "../shared/dom.js";
import {
  applyCaptionTracks,
  listAudioTracks,
  listTextTracks,
  setMediaAudioTrack,
  setMediaTextTrack,
} from "../shared/media-tracks.js";

interface DashBitrateInfo {
  readonly qualityIndex?: number;
  readonly bitrate?: number;
  readonly width?: number;
  readonly height?: number;
}

interface DashRepresentation {
  readonly id?: string;
  readonly index?: number;
  readonly bandwidth?: number;
  readonly bitrateInKbit?: number;
  readonly width?: number;
  readonly height?: number;
}

interface DashPlayer {
  initialize(media: HTMLMediaElement, url: string, autoplay: boolean): void;
  on(event: string, listener: (...args: unknown[]) => void): void;
  reset(): void;
  updateSettings(settings: unknown): void;
  /** dash.js 4.x bitrate list. */
  getBitrateInfoListFor?(type: string): readonly DashBitrateInfo[];
  /** dash.js 5.x representation list. */
  getRepresentationsByType?(type: string): readonly DashRepresentation[];
  /** dash.js 5.x full ladder, ignoring portal-size/bitrate settings. */
  getRepresentationsByTypeUnfiltered?(type: string): readonly DashRepresentation[];
  /** dash.js 4.x quality selection. */
  setQualityFor?(type: string, index: number): void;
  /** dash.js 5.x quality selection. */
  setRepresentationForTypeByIndex?(type: string, index: number, forceReplace?: boolean): void;
}

interface DashModule {
  readonly MediaPlayer: (() => { create(): DashPlayer }) & {
    readonly events?: Readonly<Record<string, string>>;
  };
}

function toQualities(levels: readonly DashBitrateInfo[]): readonly QualityLevel[] {
  return levels.map((level, index) => {
    const id = String(level.qualityIndex ?? index);
    const label = level.height === undefined ? `Level ${index + 1}` : `${level.height}p`;

    return {
      id,
      label,
      ...(level.width === undefined ? {} : { width: level.width }),
      ...(level.height === undefined ? {} : { height: level.height }),
      ...(level.bitrate === undefined ? {} : { bitrate: level.bitrate }),
    };
  });
}

/**
 * Reads the quality ladder from whichever dash.js API is available.
 *
 * dash.js 4 exposed `getBitrateInfoListFor`; dash.js 5 replaced it with
 * `getRepresentationsByType`. Supporting both keeps the documented
 * `dashjs@^5` peer range working without dropping 4.x consumers.
 */
function qualityLevelsFor(player: DashPlayer): readonly QualityLevel[] {
  const bitrates = player.getBitrateInfoListFor?.("video");

  if (bitrates !== undefined) {
    return toQualities(bitrates);
  }

  const representations =
    player.getRepresentationsByTypeUnfiltered?.("video") ??
    player.getRepresentationsByType?.("video") ??
    [];

  return representations.map((representation, index) => {
    const height = representation.height;
    const bitrate =
      representation.bandwidth ??
      (representation.bitrateInKbit === undefined
        ? undefined
        : representation.bitrateInKbit * 1_000);

    return {
      id: String(representation.index ?? index),
      label: height === undefined ? `Level ${index + 1}` : `${height}p`,
      ...(representation.width === undefined ? {} : { width: representation.width }),
      ...(height === undefined ? {} : { height }),
      ...(bitrate === undefined ? {} : { bitrate }),
    };
  });
}

/** MPEG-DASH engine backed by the optional `dashjs` peer dependency. */
export function createDashEngine(context: EngineContext): PlayerEngine {
  const { source, options, emit } = context;
  let video: HTMLVideoElement | null = null;
  let dash: DashPlayer | null = null;
  let detach: (() => void) | null = null;
  let qualities: readonly QualityLevel[] = options.qualities ?? [];

  return {
    kind: "video",
    get element() {
      return video;
    },
    capabilities: { ...NATIVE_CAPABILITIES, quality: true },

    async load(): Promise<void> {
      const element = createMediaElement("video", options);
      video = element;
      detach = bindMediaElement(element, emit);
      applyCaptionTracks(element, options.captions?.tracks ?? source.source.captions);
      context.host.append(element);

      const module = (await import("dashjs")) as unknown as DashModule;

      if (typeof module.MediaPlayer !== "function") {
        element.src = source.url;
        const metadata = waitForMetadata(element);
        element.load();
        await metadata;
        return;
      }

      const player = module.MediaPlayer().create();
      dash = player;
      const events = module.MediaPlayer.events ?? {};
      const readyEvent = events["STREAM_INITIALIZED"] ?? events["CAN_PLAY"] ?? "streamInitialized";

      await new Promise<void>((resolve) => {
        player.on(readyEvent, () => {
          qualities = qualityLevelsFor(player);
          resolve();
        });
        player.initialize(element, source.url, false);
      });

      await waitForMetadata(element);
    },

    async play(): Promise<void> {
      if (video === null) {
        throw createPlayerError("No media element is attached.", { code: "invalid-state" });
      }

      await video.play();
    },

    pause(): void {
      video?.pause();
    },

    seek(time: number): void {
      if (video !== null) {
        const duration = safeDuration(video);
        video.currentTime = duration > 0 ? clamp(time, 0, duration) : Math.max(0, time);
      }
    },

    setVolume(volume: number): void {
      if (video !== null) {
        video.volume = clamp(volume, 0, 1);
      }
    },

    setMuted(muted: boolean): void {
      if (video !== null) {
        video.muted = muted;
      }
    },

    setPlaybackRate(rate: number): void {
      if (video !== null) {
        video.playbackRate = clamp(rate, 0.25, 4);
      }
    },

    setQuality(quality: string | null): void {
      if (dash === null) {
        return;
      }

      dash.updateSettings({
        streaming: { abr: { autoSwitchBitrate: { video: quality === null } } },
      });

      if (quality !== null) {
        const index = Number(quality);

        if (typeof dash.setQualityFor === "function") {
          dash.setQualityFor("video", index);
        } else {
          dash.setRepresentationForTypeByIndex?.("video", index);
        }
      }
    },

    setTextTrack(id: string | null): void {
      if (video !== null) {
        setMediaTextTrack(video, id);
      }
    },

    setAudioTrack(id: string | null): void {
      if (video !== null) {
        setMediaAudioTrack(video, id);
      }
    },

    getQualities(): readonly QualityLevel[] {
      if (dash !== null) {
        const next = qualityLevelsFor(dash);

        if (next.length > 0) {
          qualities = next;
        }
      }

      return qualities;
    },

    getTextTracks(): readonly TextTrackInfo[] {
      return video === null ? [] : listTextTracks(video);
    },

    getAudioTracks(): readonly AudioTrackInfo[] {
      return video === null ? [] : listAudioTracks(video);
    },

    getCurrentTime(): number {
      return video?.currentTime ?? 0;
    },

    getDuration(): number {
      return video === null ? 0 : safeDuration(video);
    },

    getBuffered(): number {
      return video === null ? 0 : bufferedEnd(video);
    },

    destroy(): void {
      detach?.();
      detach = null;
      dash?.reset();
      dash = null;

      if (video !== null) {
        video.pause();
        video.removeAttribute("src");
        video.load();
        removeElement(video);
        video = null;
      }
    },
  };
}
